// ---- Pricing logic -----------------------------------------------------
// R25 per pack, but every full bundle of 10 packs is R200 instead of R250.
function calcPackPrice(qty) {
  if (qty <= 0) return 0;
  const bundles = Math.floor(qty / 10);
  const remainder = qty % 10;
  return bundles * 200 + remainder * 25;
}

function fullPriceNoDiscount(qty) {
  return qty * 25;
}

const DELIVERY_FEE = 250;
const FREEZER_PRICE = 1500;

